/* miniatura SVG de una pared, a escala (2 px/cm). photos: array opcional de URLs por hueco */
window.MOMENTURIES_wallSVG = function(w, photos, opts){
  opts = opts || {};
  var SC = 2, PAD = 6, VW = w.width*SC + PAD*2, VH = w.height*SC + PAD*2;
  var shadeBy = { cuadrado:'#8a929a', clasico:'#5f6a74', retrato:'#3a444e' };
  var out = '<svg viewBox="0 0 ' + VW.toFixed(0) + ' ' + VH.toFixed(0) + '" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="' + w.name + '">';
  w.pieces.forEach(function(pc, i){
    var x = PAD + pc.x*SC, y = PAD + pc.y*SC, ww = pc.w*SC, hh = pc.h*SC, ph = photos && photos[i];
    if(ph){
      out += '<image href="' + ph + '" x="' + x + '" y="' + y + '" width="' + ww + '" height="' + hh + '" preserveAspectRatio="xMidYMid slice"/>';
    } else {
      var fill = (opts.shade && opts.shade[pc.format]) || shadeBy[pc.format];
      out += '<rect x="' + x + '" y="' + y + '" width="' + ww + '" height="' + hh + '" rx="1.5" fill="' + fill + '" stroke="rgba(0,0,0,.18)"/>';
      if(!opts.noLabels) out += '<text x="' + (x+ww/2) + '" y="' + (y+hh/2+3.5) + '" text-anchor="middle" font-size="10" font-weight="600" fill="#fff" font-family="system-ui,sans-serif">' + pc.size + '</text>';
    }
  });
  return out + '</svg>';
};
/* ── TAMAÑO DEL CONJUNTO ──
   Un conjunto cuyas piezas son todas del mismo formato y la misma talla se puede pedir en las
   demás tallas de ese formato: es la misma composición, más grande o más pequeña.
   30-oct-2026: la separación entre cuadros NO crece con la talla (antes se escalaba todo y en la
   L salían 9 cm de hueco y en la S 1 cm), y el clásico ya no guarda la proporción entre tallas
   (S 10×15 es 2:3, las demás ~A4): por eso cada eje se escala aparte (ver MOMENTURIES_wallAt).
   Los que mezclan tallas se quedan con la suya. */
window.MOMENTURIES_wallSizeKeys = function(w){
  w = w.base || w;
  var f = w.pieces[0].format, s = w.pieces[0].size;
  for(var i = 1; i < w.pieces.length; i++) if(w.pieces[i].format !== f || w.pieces[i].size !== s) return [];
  return Object.keys(window.MOMENTURIES_FORMAT_SIZES[f]);
};
/* el conjunto w en la talla k: mismo id y nombre, piezas y medidas recalculadas.
   Lleva .base (el original) y .vk (la talla). Si k no vale, devuelve el original. */
window.MOMENTURIES_wallAt = function(w, k){
  var base = w.base || w, f = base.pieces[0].format, s = base.pieces[0].size;
  if(!k || k === s || window.MOMENTURIES_wallSizeKeys(base).indexOf(k) < 0) return base;
  var FS = window.MOMENTURIES_FORMAT_SIZES[f], INFO = window.MOMENTURIES_SIZE_INFO[f][k];
  /* los centros se mueven en cada eje lo que crece un cuadro + su separación, así el hueco entre
     vecinos se queda en base.gap (3 cm). Eje de la orientación que más se repite. */
  var g = base.gap || 3, nh = 0;
  base.pieces.forEach(function(pc){ if(pc.orient === 'h') nh++; });
  var d0 = FS[s].slice(), d1 = FS[k].slice();
  if(nh*2 > base.pieces.length){ d0.reverse(); d1.reverse(); }
  var rx = (d1[0] + g) / (d0[0] + g), ry = (d1[1] + g) / (d0[1] + g);
  var out = {}; for(var key in base) out[key] = base[key];
  out.base = base; out.vk = k;
  out.pieces = base.pieces.map(function(pc){
    var w = pc.orient === 'h' ? FS[k][1] : FS[k][0], h = pc.orient === 'h' ? FS[k][0] : FS[k][1];
    return { format:f, size:k, orient:pc.orient, x:(pc.x + pc.w/2)*rx - w/2, y:(pc.y + pc.h/2)*ry - h/2, w:w, h:h };
  });
  var x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
  out.pieces.forEach(function(pc){ x0 = Math.min(x0, pc.x); y0 = Math.min(y0, pc.y); x1 = Math.max(x1, pc.x + pc.w); y1 = Math.max(y1, pc.y + pc.h); });
  out.pieces.forEach(function(pc){ pc.x = Math.round((pc.x - x0)*100)/100; pc.y = Math.round((pc.y - y0)*100)/100; });
  out.width = Math.round((x1 - x0)*10)/10; out.height = Math.round((y1 - y0)*10)/10;
  out.price = Math.round(INFO.price*base.n*100)/100; out.soldOut = !INFO.stock;
  return out;
};
/* dónde va un conjunto según el ancho que ocupa (cm) */
window.MOMENTURIES_HUECOS = [
  { k:'s', max:65,  es:'Rincón o recibidor', en:'Nook or hallway',     esR:'hasta 65 cm',      enR:'up to 65 cm' },
  { k:'m', max:115, es:'Sobre una cómoda',   en:'Above a sideboard',   esR:'de 65 a 115 cm',   enR:'65 to 115 cm' },
  { k:'l', max:1e9, es:'Sobre el sofá',      en:'Above the sofa',      esR:'más de 115 cm',    enR:'over 115 cm' }
];
window.MOMENTURIES_huecoOf = function(width){
  var H = window.MOMENTURIES_HUECOS;
  for(var i = 0; i < H.length; i++) if(width <= H[i].max) return H[i].k;
  return H[H.length - 1].k;
};
/* Las tres funciones de abajo aceptan `ok(w)` = «este conjunto tiene existencias». Sin ella se
   usa la marca soldOut de aquí; el editor pasa la suya (FORMATS manda en el carrito). */
window.MOMENTURIES_wallVersions = function(w){
  var base = w.base || w, ks = window.MOMENTURIES_wallSizeKeys(base);
  return ks.length ? ks.map(function(k){ return window.MOMENTURIES_wallAt(base, k); }) : [base];
};
/* el conjunto en la talla k (o en la suya) si tiene existencias; si no, en la más cercana que tenga */
window.MOMENTURIES_wallPick = function(w, k, ok){
  ok = ok || function(v){ return !v.soldOut; };
  var base = w.base || w, all = window.MOMENTURIES_wallVersions(base), want = base, i, j, best = null;
  for(i = 0; i < all.length; i++) if(k && (all[i].vk || all[i].pieces[0].size) === k) want = all[i];
  if(ok(want)) return want;
  j = all.indexOf(want);
  for(i = 0; i < all.length; i++) if(ok(all[i]) && (best === null || Math.abs(i - j) < Math.abs(all.indexOf(best) - j))) best = all[i];
  return best || want;
};
/* una versión que ya existe como conjunto propio (misma forma, misma talla) no se enseña dos veces */
window.MOMENTURIES_wallTwin = function(v){
  if(!v.base) return false;
  var W = window.MOMENTURIES_WALLS;
  for(var i = 0; i < W.length; i++){
    var o = W[i];
    if(o === v.base || o.n !== v.n || !window.MOMENTURIES_wallSizeKeys(o).length || o.pieces[0].format !== v.pieces[0].format) continue;
    /* el propio conjunto o, o (si va antes en el catálogo) o llevado a esta misma talla */
    var t = o.pieces[0].size === v.vk ? o : (i < W.indexOf(v.base) ? window.MOMENTURIES_wallAt(o, v.vk) : null);
    if(t && Math.abs(t.width - v.width) < 3 && Math.abs(t.height - v.height) < 3) return true;
  }
  return false;
};
/* qué versión de un conjunto se enseña en el hueco h ('all' = sin filtrar): la mayor con
   existencias que cae en ese ancho. null = no tiene ninguna ahí. Un conjunto agotado en todas
   sus tallas sale solo en el hueco de su talla original, para enseñarlo apagado. */
window.MOMENTURIES_wallForHueco = function(w, h, ok){
  if(w.dup) return null;          // misma forma que otro conjunto: en las listas sale solo aquel
  ok = ok || function(v){ return !v.soldOut; };
  if(h === 'all') return window.MOMENTURIES_wallPick(w, null, ok);
  var all = window.MOMENTURIES_wallVersions(w), any = false, best = null;
  for(var i = 0; i < all.length; i++){
    if(!ok(all[i])) continue;
    any = true;
    if(window.MOMENTURIES_huecoOf(all[i].width) === h && !window.MOMENTURIES_wallTwin(all[i])) best = all[i];
  }
  if(!any) return window.MOMENTURIES_huecoOf(w.width) === h ? w : null;
  return best;
};
